{"security_risk":"LOW","summary":"Inspect request schemas","command":"python3 << 'EOF'
import json
d = json.load(open('/workspace/contracts/openapi.contract.json'))
paths = d['paths']

# Extract all request body schemas to understand expected requests
for p, methods in sorted(paths.items()):
    for m, op in methods.items():
        opid = op.get('operationId', '?')
        rb = op.get('requestBody', {})
        rb_content = rb.get('content', {})
        if rb_content:
            for ct, ctdef in rb_content.items():
                schema_ref = ctdef.get('schema', {})
                if '$ref' in schema_ref:
                    schema_name = schema_ref['$ref'].split('/')[-1]
                else:
                    schema_name = 'inline'
                print(f'{opid:35} {p:50} -> {ct} req={schema_name}')
        elif op.get('parameters'):
            for param in op['parameters']:
                if param.get('in') == 'path':
                    print(f'{opid:35} {p:50} -> path={param["name"]}')
                elif param.get('in') == 'query':
                    print(f'{opid:35} {p:50} -> query={param["name"]}')
EOF"}

