// role/authenticated context lookup.
package httputil

import (
	"encoding/json"
	"net/http"
)

// ErrorEnvelope mirrors the OpenAPI ErrorEnvelope schema.
type ErrorEnvelope struct {
	Error string `json:"error"`
	Code  string `json:"code"`
}

// WriteError writes an error envelope using the canonical status for each code.
// Any code that is not mapped explicitly falls back to 400.
func WriteError(w http.ResponseWriter, code string, msg string) {
	status := statusForCode(code)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(ErrorEnvelope{Error: msg, Code: code})
}

// WriteOK writes a 200 with {"data": payload}.
func WriteOK(w http.ResponseWriter, payload any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	_ = json.NewEncoder(w).Encode(map[string]any{"data": payload})
}

// WriteCreated writes a 201 with {"data": payload}.
func WriteCreated(w http.ResponseWriter, payload any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(201)
	_ = json.NewEncoder(w).Encode(map[string]any{"data": payload})
}

// DecodeJSON decodes JSON into out and returns false if it failed (already wrote the error envelope).
func DecodeJSON(r *http.Request, out any) bool {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(out); err != nil {
		WriteError(r.Context().Value("w").(http.ResponseWriter), "invalid_json", err.Error())
		return false
	}
	return true
}

func statusForCode(code string) int {
	switch code {
	case "unauthorized", "invalid_credentials":
		return http.StatusUnauthorized
	case "forbidden", "role_not_held", "ineligible_worker", "certification_inactive",
		"lab_assignment_required", "node_assignment_required", "handling_noncompliant":
		return http.StatusForbidden
	case "not_found":
		return http.StatusNotFound
	case "method_not_allowed":
		return http.StatusMethodNotAllowed
	case "starting":
		return http.StatusServiceUnavailable
	case "internal_error":
		return http.StatusInternalServerError
	}
	// All remaining codes are 409 by default — they cover idempotency, conflict,
	// state machine validation, capacity, batch, plan and replan issues.
	return http.StatusConflict
}"}

