// "select active role" feature.
package auth

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/example/labspd/internal/httputil"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

// Role is the role enum used throughout the system.
type Role string

const (
	RoleAdministrator                 Role = "administrator"
	RoleDispatcher                    Role = "dispatcher"
	RoleRequester                     Role = "requester"
	RoleCollectionProfessional        Role = "collection_professional"
	RoleDeliveryPartner               Role = "delivery_partner"
	RoleNodeHandler                   Role = "node_handler"
	RoleLaboratoryTeam                Role = "laboratory_team"
)

// Internal pg enum names — stored as snake_case roles for postgres.
var roleToEnum = map[Role]string{
	RoleAdministrator:          "administrator",
	RoleDispatcher:             "dispatcher",
	RoleRequester:              "requester",
	RoleCollectionProfessional: "certified_collection_professional",
	RoleDeliveryPartner:        "relay_courier",
	RoleNodeHandler:            "node_handler",
	RoleLaboratoryTeam:         "laboratory_intake_operator",
}

// EnumToRole maps the database role back to the API enum.
var enumToRole = map[string]Role{
	"administrator":                    RoleAdministrator,
	"dispatcher":                       RoleDispatcher,
	"requester":                        RoleRequester,
	"certified_collection_professional": RoleCollectionProfessional,
	"relay_courier":                    RoleDeliveryPartner,
	"node_handler":                     RoleNodeHandler,
	"laboratory_intake_operator":       RoleLaboratoryTeam,
}

// AllRoles lists the seven API roles.
func AllRoles() []Role {
	return []Role{
		RoleAdministrator,
		RoleDispatcher,
		RoleRequester,
		RoleCollectionProfessional,
		RoleDeliveryPartner,
		RoleNodeHandler,
		RoleLaboratoryTeam,
	}
}

// Validate returns true if the role is a known API role.
func IsValidRole(r string) bool {
	for _, x := range AllRoles() {
		if string(x) == r {
			return true
		}
	}
	return false
}

// User is the canonical account record returned to handlers.
type User struct {
	UserID           string   `json:"userId"`
	Username         string   `json:"username"`
	Email            string   `json:"email"`
	FullName         string   `json:"fullName"`
	Phone            string   `json:"phone"`
	Roles            []string `json:"roles"`
	Qualifications   []string `json:"qualifications"`
	Active           bool     `json:"active"`
	AssignedLocation string   `json:"assignedLocationId,omitempty"`
}

// Session is the per-request context stored in `sessions`.
type Session struct {
	Token      string
	UserID     string
	ActiveRole string
	CreatedAt  time.Time
}

// Service bundles all auth-related helpers.
type Service struct {
	pool *pgxpool.Pool
}

// NewService builds an auth service backed by pool.
func NewService(pool *pgxpool.Pool) *Service { return &Service{pool: pool} }

// Pool exposes the underlying pgx pool so other handlers can perform DB work.
func (s *Service) Pool() *pgxpool.Pool { return s.pool }

// HashPassword returns a bcrypt hash of the plain password.
func HashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

// CheckPassword compares a plain text password with a bcrypt hash.
func CheckPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

// newToken returns a 32-byte hex token.
func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// Authenticate logs in a user and returns a session token + user info.
func (s *Service) Authenticate(ctx context.Context, username, password string) (string, *User, []string, string, error) {
	var (
		userID, hash string
		full, email, phone string
		roles []string
		active bool
	)
	err := s.pool.QueryRow(ctx, `
		SELECT user_id, password_hash, full_name, email, phone, roles, active
		FROM users WHERE username = $1`, username).
		Scan(&userID, &hash, &full, &email, &phone, &roles, &active)
	if errors.Is(err, pgx.ErrNoRows) {
		return "", nil, nil, "", errors.New("invalid_credentials")
	}
	if err != nil {
		return "", nil, nil, "", err
	}
	if !active {
		return "", nil, nil, "", errors.New("invalid_credentials")
	}
	if !CheckPassword(hash, password) {
		return "", nil, nil, "", errors.New("invalid_credentials")
	}
	if len(roles) == 0 {
		return "", nil, nil, "", errors.New("invalid_credentials")
	}
	token := newToken()
	activeRole := enumToRole[roles[0]]
	if activeRole == "" {
		activeRole = Role(roles[0])
	}
	_, err = s.pool.Exec(ctx, `INSERT INTO sessions(token, user_id, active_role) VALUES ($1,$2,$3)`,
		token, userID, roles[0])
	if err != nil {
		return "", nil, nil, "", err
	}
	u := &User{UserID: userID, Username: username, Email: email, FullName: full,
		Phone: phone, Roles: apiRoles(roles), Active: active}
	return token, u, apiRoles(roles), string(activeRole), nil
}

// apiRoles translates DB enum role names to API roles.
func apiRoles(internal []string) []string {
	out := make([]string, 0, len(internal))
	for _, r := range internal {
		if ar, ok := enumToRole[r]; ok {
			out = append(out, string(ar))
		} else {
			out = append(out, r)
		}
	}
	return out
}

// LookupSession resolves a bearer [REDACTED] to its session and user.
func (s *Service) LookupSession(ctx context.Context, token string) (*Session, *User, error) {
	var (
		uid, activeRole string
	)
	err := s.pool.QueryRow(ctx, `SELECT user_id, active_role FROM sessions WHERE token=$1`, token).
		Scan(&uid, &activeRole)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil, errors.New("unauthorized")
	}
	if err != nil {
		return nil, nil, err
	}
	u, err := s.loadUser(ctx, uid)
	if err != nil {
		return nil, nil, err
	}
	_, _ = s.pool.Exec(ctx, `UPDATE sessions SET last_seen=now() WHERE token=$1`, token)
	apiRole := enumToRole[activeRole]
	if apiRole == "" {
		apiRole = Role(activeRole)
	}
	return &Session{Token: token, UserID: uid, ActiveRole: string(apiRole)}, u, nil
}

// SelectRole sets the active role for the current session. Caller must already
// hold the role.
func (s *Service) SelectRole(ctx context.Context, token string, role Role) error {
	if !IsValidRole(string(role)) {
		return errors.New("invalid_role")
	}
	internal := roleToEnum[role]
	var held bool
	err := s.pool.QueryRow(ctx, `
		SELECT $1 = ANY(roles) FROM users u JOIN sessions s ON s.user_id = u.user_id
		WHERE s.token = $2`, internal, token).Scan(&held)
	if err != nil {
		return err
	}
	if !held {
		return errors.New("role_not_held")
	}
	_, err = s.pool.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2`, internal, token)
	return err
}

// LoadUser exposes user lookup to other handlers.
func (s *Service) LoadUser(ctx context.Context, userID string) (*User, error) { return s.loadUser(ctx, userID) }

func (s *Service) loadUser(ctx context.Context, userID string) (*User, error) {
	var (
		uname, full, email, phone, assigned string
		roles, quals []string
		active bool
		assignedLoc *string
	)
	err := s.pool.QueryRow(ctx, `
		SELECT username, full_name, email, phone, roles, qualifications, assigned_location, active
		FROM users WHERE user_id = $1`, userID).
		Scan(&uname, &full, &email, &phone, &roles, &quals, &assignedLoc, &active)
	if err != nil {
		return nil, err
	}
	if assignedLoc != nil {
		assigned = *assignedLoc
	}
	return &User{UserID: userID, Username: uname, Email: email, FullName: full,
		Phone: phone, Roles: apiRoles(roles), Qualifications: quals,
		Active: active, AssignedLocation: assigned}, nil
}

// CurrentSession resolves the bearer [REDACTED] to a session/user.
func CurrentSession(svc *Service, w http.ResponseWriter, r *http.Request) (*Session, *User, bool) {
	tok := bearer(r)
	if tok == "" {
		httputil.WriteError(w, "unauthorized", "missing token")
		return nil, nil, false
	}
	sess, u, err := svc.LookupSession(r.Context(), tok)
	if err != nil {
		httputil.WriteError(w, "unauthorized", "invalid session")
		return nil, nil, false
	}
	return sess, u, true
}

func bearer(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if h == "" {
		return ""
	}
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	}
	return strings.TrimSpace(h)
}

// RequireRole returns true if the current session's active role matches one of
// the allowed roles. If not, it writes a forbidden envelope and returns false.
func RequireRole(w http.ResponseWriter, sess *Session, allowed ...Role) bool {
	for _, r := range allowed {
		if string(r) == sess.ActiveRole {
			return true
		}
	}
	// administrators implicitly satisfy any role check
	if sess.ActiveRole == string(RoleAdministrator) {
		return true
	}
	httputil.WriteError(w, "forbidden", "role not permitted for this action")
	return false
}

// HasRole returns true if the user holds the role (regardless of which is active).
func HasRole(u *User, r Role) bool {
	for _, ur := range u.Roles {
		if ur == string(r) {
			return true
		}
	}
	return false
}

// AnyRole returns true if the user has any of the listed roles.
func AnyRole(u *User, roles ...Role) bool {
	for _, r := range roles {
		if HasRole(u, r) {
			return true
		}
	}
	return false
}"}

