// that streams events to dispatchers / operations dashboards.
package realtime

import (
	"context"
	"sync"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Bus is a simple pub/sub of realtime events. Each subscriber receives events
// from the moment they subscribe forward.
type Bus struct {
	mu     sync.RWMutex
	subs   map[chan Event]struct{}
	pool   *pgxpool.Pool
}

// Event is a single realtime notification.
type Event struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]any         `json:"payload"`
	CreatedAt  string                 `json:"createdAt"`
}

// NewBus builds a bus. The pool is kept so events can be persisted to the
// events table by emitters (the bus itself does not persist).
func NewBus(pool *pgxpool.Pool) *Bus { return &Bus{subs: map[chan Event]struct{}{}, pool: pool} }

// Subscribe registers a new subscriber channel. The returned channel receives
// every event published from that point onward. closeWhenDone should be
// invoked when the consumer disconnects.
func (b *Bus) Subscribe() (chan Event, func()) {
	ch := make(chan Event, 64)
	b.mu.Lock()
	b.subs[ch] = struct{}{}
	b.mu.Unlock()
	return ch, func() {
		b.mu.Lock()
		if _, ok := b.subs[ch]; ok {
			delete(b.subs, ch)
			close(ch)
		}
		b.mu.Unlock()
	}
}

// Publish fans out an event to all subscribers and persists it to events.
func (b *Bus) Publish(ctx context.Context, evtType, entityType, entityID string, payload map[string]any) {
	row := b.pool.QueryRow(ctx, `
		INSERT INTO events (event_type, payload)
		VALUES ($1, $2)
		RETURNING id, occurred_at`,
		evtType, payloadJSON(payload))
	var id int64
	var ts string
	if err := row.Scan(&id, &ts); err != nil {
		return
	}
	evt := Event{ID: id, Type: evtType, EntityType: entityType, EntityID: entityID,
		Payload: payload, CreatedAt: ts}
	b.mu.RLock()
	defer b.mu.RUnlock()
	for ch := range b.subs {
		select {
		case ch <- evt:
		default:
		}
	}
}"}

